// Shapes that once left part of a secret behind after Cover it, and lines that once got glued onto a whole key.
// Every value is made up: generated by tests/fixtures/secrets.js or built from obviously fake parts.
// Run from the repo root:  node --test tests/engine-leaks.test.js
"use strict";

const test = require("node:test");
const assert = require("node:assert/strict");

require("../extension/patterns.js");
require("../extension/detector.js");
const { makeSecrets } = require("./fixtures/secrets.js");
const { generatedCases, wrappersFor } = require("./fuzz/structure.js");

const SEED = 20261020;
const FIXTURES = makeSecrets(SEED);
const valueOf = (kind) => FIXTURES.find((fixture) => fixture.kind === kind).value;
const detect = (text) => globalThis.Clotr.detect(text);
const cover = (text) => globalThis.Clotr.redact(text, detect(text));
const BS = "\\";
const PW = ["Zq7v", "Nw3T", "fLm9", "xKp2"].join("");

// Any 8-character run (or `min`) of the secret still in the covered text, read as written, with percent escapes
// undone, and with quote marks, line breaks and Markdown escapes taken out.
function leftOf(secret, out, min = 8) {
  const decoded = (s) => s.replace(/%([0-9A-Fa-f]{2})/g, (_m, hex) => String.fromCharCode(parseInt(hex, 16)));
  const plain = (s) =>
    decoded(s)
      .replace(/\[REDACTED [^\]]*\]/g, "\u0000")
      .replace(/^[ \t]*(?:>[ \t]?)+/gm, "")
      .replace(/\\(?=_)/g, "")
      .replace(/[\s"'\\]/g, "");
  const body = plain(secret);
  const rest = plain(out);
  for (let i = 0; i + min <= body.length; i++) if (rest.includes(body.slice(i, i + min))) return body.slice(i, i + min);
  return "";
}

function expectGone(text, ...secrets) {
  const out = cover(text);
  for (const secret of secrets) {
    assert.equal(leftOf(secret, out), "", `${JSON.stringify(text)} → ${JSON.stringify(out)}`);
  }
  return out;
}

const kindsOf = (text) => detect(text).map((result) => result.id);

// ---------- %40 in a URL's user part ----------

test("a connection string with an encoded @ in its user name is found and its password covered", () => {
  for (const text of [
    `mysql://svc%40acct:${PW}@10.1.2.3:3306/db`,
    `postgres://appuser%40myserver:${PW}@myserver.postgres.database.azure.com:5432/app`,
    `DATABASE_URL=postgresql://appuser%40myserver:${PW}@myserver.example.test/app?sslmode=require`,
    // Azure's own form, typed without encoding
    `mysql://svc@acct:${PW}@db.example.test:3306/db`,
  ]) {
    assert.ok(kindsOf(text).includes("connection_string"), `${text} → ${kindsOf(text)}`);
    expectGone(text, PW);
  }
  // An encoded @ in the password itself
  const split = `postgres://app:${PW.slice(0, 8)}%40${PW.slice(8)}@db.example.test/app`;
  assert.ok(kindsOf(split).includes("connection_string"), `${split} → ${kindsOf(split)}`);
  expectGone(split, PW.slice(0, 8), PW.slice(8));
});

test("an encoded @ in a link's query or path is still an email, and a plain web address stays quiet", () => {
  assert.deepEqual(
    detect("https://example.com/signup?email=ann%40gmail.com&ref=x").find((r) => r.id === "email")?.matches,
    ["ann%40gmail.com"],
  );
  for (const quiet of [
    "see https://example.test:8080/status for details",
    "https://example.test/a%2Fb?next=%2Fhome%3Fx%3D1",
  ]) {
    assert.deepEqual(kindsOf(quiet), [], quiet);
  }
  // A user name before a host and port is not a password.
  for (const text of ["https://me@example.test:8080/a@b", "http://deploy@build.example.test:443/x@y"]) {
    assert.ok(!kindsOf(text).includes("connection_string"), text);
  }
});

// ---------- +driver schemes ----------

test("a connection string with a +driver scheme is found and its password covered", () => {
  for (const scheme of [
    "postgresql+psycopg2",
    "postgresql+asyncpg",
    "postgres+pg8000",
    "mysql+pymysql",
    "mysql+aiomysql",
    "mssql+pyodbc",
    "oracle+cx_oracle",
    "mariadb+mariadbconnector",
  ]) {
    for (const host of ["localhost", "db.example.test:5432", "10.1.2.3"]) {
      const text = `SQLALCHEMY_DATABASE_URI = "${scheme}://app:${PW}@${host}/orders"`;
      assert.ok(kindsOf(text).includes("connection_string"), `${text} → ${kindsOf(text)}`);
      expectGone(text, PW);
    }
  }
});

// ---------- URL-encoded values ----------

test("a secret URL-encoded into a link's query is found and covered", () => {
  const misses = [];
  for (const fixture of FIXTURES) {
    const text = `https://example.test/callback?state=abc&value=${encodeURIComponent(fixture.value)}&next=%2Fhome`;
    const results = detect(text);
    const left = leftOf(fixture.value, globalThis.Clotr.redact(text, results));
    if (!results.length || left) misses.push(`${fixture.kind}: ${results.map((r) => r.id)} left ${left}`);
  }
  assert.deepEqual(misses, []);
});

test("personal details URL-encoded into a query are found and covered", () => {
  for (const [value, kind] of [
    ["4539 1488 0343 6467", "credit_card"],
    ["3782 822463 10005", "credit_card"],
    ["(415) 555-0132", "phone_number"],
    ["+44 20 7946 0958", "phone_number"],
    ["GB33 BUKB 2020 1555 5555 55", "bank_account"],
  ]) {
    const text = `https://example.test/form?ref=7&field=${encodeURIComponent(value)}`;
    assert.ok(kindsOf(text).includes(kind), `${text} → ${kindsOf(text)}`);
    const out = cover(text);
    assert.ok(!decodeURIComponent(out.replace(/\[REDACTED [^\]]*\]/g, "")).includes(value), `${text} → ${out}`);
  }
});

test("ordinary encoded links stay quiet", () => {
  for (const quiet of [
    "https://example.test/search?q=hello%20world%21&lang=en",
    "https://example.test/a%2Fb%2Fc?redirect=%2Fsettings%3Ftab%3D2",
    "100%25 done, see https://example.test/p?x=1%2C2%2C3",
    "the sale is 20%OFF today",
  ]) {
    assert.deepEqual(kindsOf(quiet), [], quiet);
  }
});

// ---------- Markdown-escaped underscores ----------

test("a key with Markdown-escaped underscores is found as its own kind and covered", () => {
  const escape = (s) => s.replace(/_/g, `${BS}_`);
  for (const kind of ["github_token", "stripe_secret_key", "linear_key", "replicate_token", "digitalocean_token"]) {
    const value = valueOf(kind);
    assert.ok(value.includes("_"), kind);
    for (const text of [
      escape(value),
      `Here is the key ${escape(value)} for staging`,
      `${escape("API_KEY")}=${escape(value)}`,
    ]) {
      assert.ok(kindsOf(text).includes(kind), `${text} → ${kindsOf(text)}`);
      expectGone(text, value);
    }
  }
  for (const quiet of [`my${BS}_variable${BS}_name`, `call ${BS}_${BS}_init${BS}_${BS}_ first`]) {
    assert.deepEqual(kindsOf(quiet), [], quiet);
  }
});

// ---------- Wrapped onto indented, quoted and YAML-folded lines ----------

const wrapAt = (value, width) => value.match(new RegExp(`.{1,${width}}`, "g"));

test("a key wrapped onto indented, tab-indented, email-quoted or YAML-folded lines is covered whole", () => {
  for (const kind of ["openai_key", "anthropic_key", "github_token", "slack_token", "atlassian_token", "jwt"]) {
    const value = valueOf(kind);
    const parts = wrapAt(value, 24);
    for (const text of [
      `OPENAI_API_KEY=${parts.join("\n    ")}`,
      `token:\n    ${parts.join("\n    ")}`,
      `token:\n\t${parts.join("\n\t")}`,
      `> here is the key\n> ${parts.join("\n> ")}\n> thanks`,
      `>> ${parts.join("\n>> ")}`,
      `api_key: >\n  ${parts.join("\n  ")}\nnext: 1`,
      `api_key: >-\n    ${parts.join("\n    ")}`,
    ]) {
      assert.ok(kindsOf(text).includes(kind), `${kind}: ${JSON.stringify(text)} → ${kindsOf(text)}`);
      expectGone(text, value);
    }
  }
});

test("indented code and quoted prose are not glued together", () => {
  for (const quiet of [
    "    someVeryLongIdentifierName\n    anotherIdentifierHereToo()",
    "def handler(event):\n    configurationSettings\n    return loadEverythingFromDisk",
    "> I think the deployment pipeline\n> broke yesterday afternoon",
    "summary: >\n  the deployment pipeline\n  broke yesterday afternoon",
  ]) {
    assert.deepEqual(kindsOf(quiet), [], quiet);
  }
  const github = valueOf("github_token");
  for (const text of [
    `  token: ${github}\n  region: us-east-1`,
    `> token: ${github}\n> regionSettingsName: x`,
    `    key = "${github}"\n    timeoutSeconds = 30`,
  ]) {
    const found = detect(text).find((r) => r.id === "github_token");
    assert.deepEqual(found?.matches, [github], JSON.stringify(text));
  }
});

// ---------- The next line after a whole key stays the person's own ----------

const PREFIXED = [
  "aws_access_key",
  "github_token",
  "stripe_secret_key",
  "anthropic_key",
  "openai_key",
  "xai_key",
  "google_api_key",
  "slack_token",
  "gitlab_token",
  "perplexity_key",
  "digitalocean_token",
  "huggingface_token",
  "heroku_token",
  "sentry_token",
  "grafana_token",
  "vault_token",
  "replicate_token",
  "linear_key",
  "postman_key",
  "shopify_token",
  "atlassian_token",
  "netlify_token",
  "pulumi_token",
  "databricks_token",
];
const NEXT_LINES = [
  "B=2",
  "X=1",
  "2026",
  "Z7",
  "console.log(x)",
  "3f2b8c1e-9a4d-4c7b-8e2f-1a6d5b9c0e47",
  "2026-10-21T10:00:00Z",
  "2026-10-21 10:00:00",
];

test("a whole key followed by a short or unrelated line is found as exactly the key, as its own kind", () => {
  const wrong = [];
  for (const kind of PREFIXED) {
    const value = valueOf(kind);
    for (const label of ["", "token: "]) {
      for (const eol of ["\n", "\r\n"]) {
        for (const next of NEXT_LINES) {
          const text = `${label}${value}${eol}${next}`;
          const found = detect(text).find((r) => r.id === kind);
          if (!found || found.matches.length !== 1 || found.matches[0] !== value) {
            wrong.push(
              `${kind} + ${JSON.stringify(eol + next)}: ${JSON.stringify(detect(text).map((r) => [r.id, r.matches]))}`,
            );
            continue;
          }
          const out = cover(text);
          if (!out.endsWith(`${eol}${next}`)) {
            wrong.push(`${kind} + ${JSON.stringify(eol + next)}: covered as ${JSON.stringify(out)}`);
          }
        }
      }
    }
  }
  assert.deepEqual(wrong, []);
});

test("a key wrapped with its last few characters on a line of their own is still covered whole", () => {
  const github = valueOf("github_token");
  assert.equal(cover(`token: ${github.slice(0, -2)}\n${github.slice(-2)}`), "token: [REDACTED GITHUB TOKEN]");
  for (const kind of ["openai_key", "anthropic_key", "slack_token", "atlassian_token"]) {
    const value = valueOf(kind);
    for (const width of [40, 64, 76]) {
      const text = wrapAt(`SECRET_VALUE=${value}`, width).join("\n");
      expectGone(text, value);
    }
  }
});

test("a wrapped key with a word like Thanks on the line under it is still found, and the word stays", () => {
  const wrong = [];
  for (const fixture of FIXTURES) {
    if (/\s/.test(fixture.value) || fixture.value.length <= 24) continue;
    const parts = wrapAt(fixture.value, 24);
    // Only the word's effect is tested here: a value this narrow wrap splits mid-label (a bot token's "id:", a
    // connection string's host) is a separate gap.
    if (leftOf(fixture.value, cover(parts.join("\n")))) continue;
    for (const word of ["thanks", "Thanks.", "cheers"]) {
      for (const text of [`${parts.join("\n")}\n${word}`, `> here it is\n> ${parts.join("\n> ")}\n> ${word}`]) {
        const out = cover(text);
        if (leftOf(fixture.value, out) || !out.endsWith(word)) wrong.push(`${fixture.kind}: ${JSON.stringify(out)}`);
      }
    }
  }
  assert.deepEqual(wrong, []);
});

test("a key wrapped right after its prefix is covered whole, with or without text after it", () => {
  const npmrc = FIXTURES.find((f) => f.kind === "service_token").shapes.find((s) => s.name === "npmrcWrap64");
  const keys = [
    ...["github_token", "openai_key", "anthropic_key", "slack_token", "aws_access_key", "stripe_secret_key"].map(
      valueOf,
    ),
    ...["google_api_key", "huggingface_token", "gitlab_token"].map(valueOf),
    npmrc.value.replace(/\r?\n/g, ""),
  ];
  const wrong = [];
  for (const key of keys) {
    const prefix = /^(?:sk-(?:proj|ant)-|[sr]k_(?:live|test)_|glpat-|xox[a-z]-|gh[a-z]_|AKIA|AIza|hf_|npm_)/.exec(
      key,
    )[0];
    for (const cut of new Set([prefix.length, prefix.length + 2, 8, 12])) {
      for (const after of ["", "\n\nThanks, see you", "\nThanks", "\nthanks for the help"]) {
        const text = `my key is ${key.slice(0, cut)}\n${key.slice(cut)}${after}`;
        const out = cover(text);
        if (leftOf(key, out) || !out.endsWith(after) || out.includes(`${key.slice(0, cut)}\n`)) {
          wrong.push(`${JSON.stringify(text)} → ${JSON.stringify(out)}`);
        }
      }
    }
  }
  assert.deepEqual(wrong, []);
});

// ---------- The no-residual property's wrapper forms ----------

test("every wrapper form of every generated secret is found and leaves nothing behind", () => {
  const misses = [];
  for (const candidate of generatedCases(SEED)) {
    for (const form of wrappersFor(candidate)) {
      const results = detect(form.text);
      if (form.detect && !results.length) {
        misses.push(`${candidate.kind}:${candidate.name}:${form.name} not found`);
        continue;
      }
      // 12 characters, as the fuzz property reads it: a value's own "https://" or "TWILIO_A" label can stay.
      const left = leftOf(candidate.value, globalThis.Clotr.redact(form.text, results), 12);
      if (left) misses.push(`${candidate.kind}:${candidate.name}:${form.name} left ${left}`);
    }
  }
  assert.deepEqual(misses, []);
});
